31	int32_t test_set_attr(
32	    int32_t my_pe, int32_t n_pes, uint64_t local_mem_size, const char* ip_port, aclshmemx_init_attr_t* attributes)
33	{
34	    SHM_ASSERT_RETURN(local_mem_size <= ACLSHMEM_MAX_LOCAL_SIZE, ACLSHMEM_INVALID_VALUE);
35	    SHM_ASSERT_RETURN(n_pes <= ACLSHMEM_MAX_PES, ACLSHMEM_INVALID_VALUE);
36	    SHM_ASSERT_RETURN(my_pe < ACLSHMEM_MAX_PES, ACLSHMEM_INVALID_VALUE);
37	    size_t ip_len = 0;
38	    if (ip_port != nullptr) {
39	        ip_len = std::min(strlen(ip_port), sizeof(g_ipport) - 1);
40	
41	        std::copy_n(ip_port, ip_len, attributes->ip_port);
42	        if (attributes->ip_port[0] == '\0') {
43	            SHM_LOG_ERROR("my_pe:" << my_pe << " ip_port is nullptr!");
44	            return ACLSHMEM_INVALID_VALUE;
45	        }
46	    } else {
47	        SHM_LOG_WARN("init with my_pe:" << my_pe << " ip_port is nullptr!");
48	    }
49	
50	    int attr_version = (1 << 16) + sizeof(aclshmemx_init_attr_t);
51	    attributes->my_pe = my_pe;
52	    attributes->n_pes = n_pes;
53	    attributes->ip_port[ip_len] = '\0';
54	    attributes->local_mem_size = local_mem_size;
55	    attributes->option_attr = {attr_version, ACLSHMEM_DATA_OP_MTE, DEFAULT_TIMEOUT, DEFAULT_TIMEOUT, DEFAULT_TIMEOUT};
56	    attributes->comm_args = reinterpret_cast<void*>(&default_flag_uid);
57	    aclshmemx_uniqueid_t* uid_args = (aclshmemx_uniqueid_t*)(attributes->comm_args);
58	
59	    return ACLSHMEM_SUCCESS;
60	}
