253	void test_mutil_task(std::function<void(int, int, uint64_t)> func, uint64_t local_mem_size, int process_count)
254	{
255	    pid_t pids[process_count];
256	    int status[process_count];
257	    for (int i = 0; i < process_count; ++i) {
258	        pids[i] = fork();
259	        if (pids[i] < 0) {
260	            std::cout << "fork failed ! " << pids[i] << std::endl;
261	        } else if (pids[i] == 0) {
262	            func(i + test_first_rank, test_global_ranks, local_mem_size);
263	            raise(::testing::Test::HasFailure() ? SIGUSR2 : SIGUSR1);
264	        }
265	    }
266	    for (int i = 0; i < process_count; ++i) {
267	        waitpid(pids[i], &status[i], 0);
268	        if (WIFSIGNALED(status[i])) {
269	            int sig = WTERMSIG(status[i]);
270	            if (sig != SIGUSR1) {
271	                FAIL();
272	            }
273	        } else {
274	            FAIL();
275	        }
276	    }
277	}
