279	static ssize_t read_full(int fd, void* buf, size_t count)
280	{
281	    size_t total = 0;
282	    while (total < count) {
283	        ssize_t n = read(fd, static_cast<char*>(buf) + total, count - total);
284	        if (n < 0) {
285	            if (errno == EINTR) {
286	                continue;
287	            }
288	            return -1;
289	        }
290	        if (n == 0) {
291	            return static_cast<ssize_t>(total);
292	        }
293	        total += static_cast<size_t>(n);
294	    }
295	    return static_cast<ssize_t>(total);
296	}
297	
298	static ssize_t write_full(int fd, const void* buf, size_t count)
299	{
300	    size_t total = 0;
301	    while (total < count) {
302	        ssize_t n = write(fd, static_cast<const char*>(buf) + total, count - total);
303	        if (n < 0) {
304	            if (errno == EINTR) {
305	                continue;
306	            }
307	            return -1;
308	        }
309	        total += static_cast<size_t>(n);
310	    }
311	    return static_cast<ssize_t>(total);
312	}
