314	void test_mutil_task_with_uid(
315	    std::function<void(int, int, uint64_t, aclshmemx_uniqueid_t&)> func, uint64_t local_mem_size, int process_count)
316	{
317	    if (process_count == 0) {
318	        return;
319	    }
320	
321	    pid_t pids[process_count];
322	    int status[process_count];
323	
324	    std::vector<std::array<int, 2>> dist_pipes(process_count);
325	    std::array<int, 2> uid_pipe;
326	    if (pipe(uid_pipe.data()) != 0) {
327	        ADD_FAILURE() << "pipe(uid_pipe) failed: " << strerror(errno);
328	        return;
329	    }
330	
331	    for (int i = 0; i < process_count; ++i) {
332	        if (pipe(dist_pipes[i].data()) != 0) {
333	            ADD_FAILURE() << "pipe(dist_pipes[" << i << "]) failed: " << strerror(errno);
334	            close(uid_pipe[0]);
335	            close(uid_pipe[1]);
336	            for (int k = 0; k < i; ++k) {
337	                close(dist_pipes[k][0]);
338	                close(dist_pipes[k][1]);
339	                kill(pids[k], SIGKILL);
340	                waitpid(pids[k], &status[k], 0);
341	            }
342	            return;
343	        }
344	        pids[i] = fork();
345	        if (pids[i] < 0) {
346	            ADD_FAILURE() << "fork[" << i << "] failed: " << strerror(errno);
347	            close(uid_pipe[0]);
348	            close(uid_pipe[1]);
349	            for (int k = 0; k <= i; ++k) {
350	                close(dist_pipes[k][0]);
351	                close(dist_pipes[k][1]);
352	            }
353	            for (int k = 0; k < i; ++k) {
354	                kill(pids[k], SIGKILL);
355	                waitpid(pids[k], &status[k], 0);
356	            }
357	            return;
358	        }
359	        if (pids[i] == 0) {
360	            close(uid_pipe[0]);
361	            for (int j = 0; j < process_count; ++j) {
362	                close(dist_pipes[j][1]);
363	                if (j != i) {
364	                    close(dist_pipes[j][0]);
365	                }
366	            }
367	
368	            aclshmemx_uniqueid_t uid{};
369	            if (i == 0) {
370	                setenv("SHMEM_UID_SESSION_ID", "127.0.0.1:8666", 1);
371	                int ret = aclshmemx_get_uniqueid(&uid);
372	                if (ret != ACLSHMEM_SUCCESS || uid.version != ACLSHMEM_UNIQUEID_VERSION) {
373	                    ret = (ret != ACLSHMEM_SUCCESS) ? ret : ACLSHMEM_INVALID_VALUE;
374	                }
375	                if (write_full(uid_pipe[1], &ret, sizeof(ret)) != sizeof(ret) ||
376	                    write_full(uid_pipe[1], &uid, sizeof(uid)) != sizeof(uid)) {
377	                    close(uid_pipe[1]);
378	                    raise(SIGUSR2);
379	                }
380	                close(uid_pipe[1]);
381	                func(i + test_first_rank, test_global_ranks, local_mem_size, uid);
382	                raise(::testing::Test::HasFailure() ? SIGUSR2 : SIGUSR1);
383	            }
384	            close(uid_pipe[1]);
385	
386	            if (read_full(dist_pipes[i][0], &uid, sizeof(uid)) != sizeof(uid)) {
387	                close(dist_pipes[i][0]);
388	                raise(SIGUSR2);
389	            }
390	            close(dist_pipes[i][0]);
391	
392	            func(i + test_first_rank, test_global_ranks, local_mem_size, uid);
393	            raise(::testing::Test::HasFailure() ? SIGUSR2 : SIGUSR1);
394	        }
395	    }
396	
397	    close(uid_pipe[1]);
398	    close(dist_pipes[0][1]);
399	    for (int i = 0; i < process_count; ++i) {
400	        close(dist_pipes[i][0]);
401	    }
402	
403	    aclshmemx_uniqueid_t uid{};
404	    int get_uid_ret = ACLSHMEM_SUCCESS;
405	    if (read_full(uid_pipe[0], &get_uid_ret, sizeof(get_uid_ret)) != sizeof(get_uid_ret) ||
406	        read_full(uid_pipe[0], &uid, sizeof(uid)) != sizeof(uid)) {
407	        ADD_FAILURE() << "read uid_pipe failed: " << strerror(errno);
408	        close(uid_pipe[0]);
409	        for (int i = 1; i < process_count; ++i) {
410	            close(dist_pipes[i][1]);
411	        }
412	        for (int i = 0; i < process_count; ++i) {
413	            kill(pids[i], SIGKILL);
414	            waitpid(pids[i], &status[i], 0);
415	        }
416	        return;
417	    }
418	    close(uid_pipe[0]);
419	
420	    if (get_uid_ret != ACLSHMEM_SUCCESS) {
421	        ADD_FAILURE() << "aclshmemx_get_uniqueid failed in rank 0, ret=" << get_uid_ret;
422	        for (int i = 1; i < process_count; ++i) {
423	            close(dist_pipes[i][1]);
424	        }
425	        for (int i = 0; i < process_count; ++i) {
426	            kill(pids[i], SIGKILL);
427	            waitpid(pids[i], &status[i], 0);
428	        }
429	        return;
430	    }
431	
432	    for (int i = 1; i < process_count; ++i) {
433	        if (write_full(dist_pipes[i][1], &uid, sizeof(uid)) != sizeof(uid)) {
434	            ADD_FAILURE() << "write dist_pipes[" << i << "] failed: " << strerror(errno);
435	            close(dist_pipes[i][1]);
436	            for (int k = i + 1; k < process_count; ++k) {
437	                close(dist_pipes[k][1]);
438	            }
439	            for (int k = 0; k < process_count; ++k) {
440	                kill(pids[k], SIGKILL);
441	            }
442	            for (int k = 0; k < process_count; ++k) {
443	                waitpid(pids[k], &status[k], 0);
444	            }
445	            return;
446	        }
447	        close(dist_pipes[i][1]);
448	    }
449	
450	    for (int i = 0; i < process_count; ++i) {
451	        pid_t pid_ret = waitpid(pids[i], &status[i], 0);
452	        if (pid_ret == -1) {
453	            ADD_FAILURE() << "waitpid[" << i << "] failed: " << strerror(errno);
454	            continue;
455	        }
456	        if (WIFSIGNALED(status[i])) {
457	            int sig = WTERMSIG(status[i]);
458	            if (sig != SIGUSR1) {
459	                FAIL();
460	            }
461	        } else {
462	            FAIL();
463	        }
464	    }
465	}
