467	// UID init/finalize loop helper.  In each iteration rank 0 calls
468	// aclshmemx_get_uniqueid() to obtain a fresh UID (with a fresh socket fd
469	// and magic), then distributes it to the other ranks through
470	// pre-created pipes.  All ranks call func(), barrier, then finalize.
471	void test_mutil_task_uid_loop(
472	    std::function<void(int, int, uint64_t, aclshmemx_uniqueid_t&)> func, uint64_t local_mem_size, int process_count,
473	    int loop_count)
474	{
475	    if (process_count == 0) {
476	        return;
477	    }
478	
479	    const char* session_id = "127.0.0.1:8666";
480	
481	    pid_t pids[process_count];
482	    int status[process_count];
483	
484	    // pipes for rank-0 → other-ranks UID distribution (intra-iteration)
485	    std::vector<std::array<int, 2>> uid_to_rank(process_count);
486	    for (int i = 1; i < process_count; ++i) {
487	        if (pipe(uid_to_rank[i].data()) != 0) {
488	            ADD_FAILURE() << "pipe(uid_to_rank[" << i << "]) failed: " << strerror(errno);
489	            return;
490	        }
491	    }
492	
493	    for (int i = 0; i < process_count; ++i) {
494	        pids[i] = fork();
495	        if (pids[i] < 0) {
496	            ADD_FAILURE() << "fork[" << i << "] failed: " << strerror(errno);
497	            for (int k = 0; k < i; ++k) {
498	                kill(pids[k], SIGKILL);
499	                waitpid(pids[k], &status[k], 0);
500	            }
501	            for (int j = 1; j < process_count; ++j) {
502	                close(uid_to_rank[j][0]);
503	                close(uid_to_rank[j][1]);
504	            }
505	            return;
506	        }
507	        if (pids[i] == 0) {
508	            // --- child ---
509	            if (i == 0) {
510	                setenv("SHMEM_UID_SESSION_ID", session_id, 1);
511	                for (int j = 1; j < process_count; ++j) {
